using UnityEngine;using UnityEngine.UI;
public sealed partial class TrainingOverlay
{
 GameObject inputOptions;TrainingInputConfig inputOptionsConfig;readonly System.Collections.Generic.List<Button> inputChordButtons=new System.Collections.Generic.List<Button>();
 public bool OptionInputSettingsVisible{get;private set;}
 void CreateInputOptions(){inputOptionsConfig=TrainingInputConfig.Runtime(Resources.Load<TrainingInputConfig>("TrainingInputConfig"));if(inputOptionsConfig==null||inputOptionsConfig.layoutVersion<2)return;OptionButton("NavDummy","ダミー設定",optionPanel,()=>ShowInputOptions(false));OptionButton("NavInputs","入力設定",optionPanel,()=>ShowInputOptions(true));inputOptions=OptionObject("InputSettings",optionPanel);OptionText("Header","同時押し設定（1P / 2P共通）",inputOptions.transform,15);for(int i=0;i<4;i++){int index=i;inputChordButtons.Add(OptionButton("Chord"+i,"",inputOptions.transform,()=>{if(index==0)inputOptionsConfig.special1ChordEnabled=!inputOptionsConfig.special1ChordEnabled;else if(index==1)inputOptionsConfig.special2ChordEnabled=!inputOptionsConfig.special2ChordEnabled;else if(index==2)inputOptionsConfig.fdChordEnabled=!inputOptionsConfig.fdChordEnabled;else inputOptionsConfig.throwChordEnabled=!inputOptionsConfig.throwChordEnabled;RefreshInputOptions();}));}OptionButton("Parry","パリィ（将来・無効）",inputOptions.transform,null,false);OptionText("InputNote","単発は同時押し待ち約30msの試作。専用U / I / TRCは即時。\nOFFにしても専用キーは使えます。設定変更はこの実行中のみ。\nSpecial2・パリィ・前転・assistは技／動作未実装。",inputOptions.transform,12);ShowInputOptions(false);}
 public void ShowInputOptions(bool visible){ShowTrainingOptions(false);ShowComparisonOptions(false);ShowLocomotionOptions(false);if(inputOptions==null)return;OptionInputSettingsVisible=visible;foreach(Transform child in optionPanel){if(child.name=="Title"||child.name=="Close"||child.name=="Pause"||child.name=="NavDummy"||child.name=="NavInputs"||child.name=="InputSettings"||child.name=="NavLocomotion"||child.name=="LocomotionSettings"||child.name=="NavComparison"||child.name=="ComparisonSettings"||child.name=="NavTraining"||child.name=="TrainingSettings")continue;child.gameObject.SetActive(!visible&&child.name!="Navigation");}inputOptions.SetActive(visible);RefreshInputOptions();}
 void RefreshInputOptions(){if(inputOptionsConfig==null)return;bool[] values={inputOptionsConfig.special1ChordEnabled,inputOptionsConfig.special2ChordEnabled,inputOptionsConfig.fdChordEnabled,inputOptionsConfig.throwChordEnabled};string[] names={"Special1: 弱P＋強P","Special2: 弱K＋強K（技未実装）","FD／前転: 弱P＋弱K","投げ: 中P＋中K"};for(int i=0;i<inputChordButtons.Count;i++){inputChordButtons[i].GetComponentInChildren<Text>().text=names[i]+(values[i]?"  ON":"  OFF");inputChordButtons[i].GetComponent<Image>().color=values[i]?new Color(.25f,.48f,.36f):new Color(.14f,.22f,.20f);}}
 void LayoutInputOptions(float w,float h,float left,float x,float right){if(inputOptions==null)return;OptionPlace((RectTransform)optionPanel.Find("NavDummy"),18,62,left-24,32);OptionPlace((RectTransform)optionPanel.Find("NavInputs"),18,101,left-24,32);OptionPlace((RectTransform)inputOptions.transform,x,62,right,h-112);OptionPlace((RectTransform)inputOptions.transform.Find("Header"),0,0,right,26);for(int i=0;i<inputChordButtons.Count;i++)OptionPlace((RectTransform)inputChordButtons[i].transform,0,38+i*42,right,34);OptionPlace((RectTransform)inputOptions.transform.Find("Parry"),0,208,right,32);OptionPlace((RectTransform)inputOptions.transform.Find("InputNote"),0,254,right,80);RefreshInputOptions();}
}
